package dev.mando;
import io.papermc.paper.dialog.Dialog;import io.papermc.paper.registry.data.dialog.DialogBase;import io.papermc.paper.registry.data.dialog.body.DialogBody;import io.papermc.paper.registry.data.dialog.type.DialogType;import net.kyori.adventure.text.Component;import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import java.util.*;
public final class SocialCommands implements CommandExecutor,TabCompleter{private final MandoPlugin plugin;private final TpaManager tpa;private final MailManager mail;private final HomeManager homes;public SocialCommands(MandoPlugin p,TpaManager t,MailManager m,HomeManager h){plugin=p;tpa=t;mail=m;homes=h;}public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p))return true;String n=c.getName().toLowerCase(Locale.ROOT);if(n.equals("tptoggle")){p.sendMessage("§6Mando §8» "+(tpa.toggle(p)?"§aTPA activado":"§cTPA desactivado"));return true;}if(n.equals("tpaccept")){p.sendMessage(tpa.accept(p));return true;}if(n.equals("tpdeny")){p.sendMessage(tpa.deny(p));return true;}if(n.equals("tpcancel")){p.sendMessage(tpa.cancel(p));return true;}if(n.equals("tpa")||n.equals("tpahere")){if(a.length<1)return true;Player to=Bukkit.getPlayerExact(a[0]);p.sendMessage(to==null?"§cJugador offline.":tpa.request(p,to,n.equals("tpahere")));return true;}if(n.equals("mail")){if(a.length<2){p.sendMessage("§c/mail <jugador> <mensaje>");return true;}OfflinePlayer to=Bukkit.getOfflinePlayer(a[0]);if(!to.hasPlayedBefore()&&!to.isOnline()){p.sendMessage("§cJugador desconocido.");return true;}String text=String.join(" ",Arrays.copyOfRange(a,1,a.length));if(text.length()>500){p.sendMessage("§cMáximo 500 caracteres.");return true;}p.sendMessage(mail.send(p.getUniqueId(),p.getName(),to.getUniqueId(),to.getName()==null?a[0]:to.getName(),text));return true;}if(n.equals("profile")){Player t=p;if(a.length>0){if(!p.hasPermission("mando.profile.others"))return true;t=Bukkit.getPlayerExact(a[0]);if(t==null){p.sendMessage("§cEn esta build el perfil ajeno requiere jugador online.");return true;}}Player target=t;String body=target.getName()+"\nUUID: "+target.getUniqueId()+"\nHomes: "+homes.all(target.getUniqueId()).size()+"\nMail: "+mail.unread(target.getUniqueId())+" sin leer / "+mail.total(target.getUniqueId())+" total\nTPA: "+(tpa.disabled(target)?"desactivado":"activo")+"\nTiempo jugado: "+(target.getStatistic(Statistic.PLAY_ONE_MINUTE)/1200)+" min";p.showDialog(Dialog.create(x->x.empty().base(DialogBase.builder(Component.text("Perfil · "+target.getName())).body(List.of(DialogBody.plainMessage(Component.text(body)))).build()).type(DialogType.notice())));return true;}return true;}public List<String> onTabComplete(CommandSender s,Command c,String l,String[] a){if(a.length!=1)return List.of();String q=a[0].toLowerCase(Locale.ROOT);return Bukkit.getOnlinePlayers().stream().map(Player::getName).filter(x->x.toLowerCase(Locale.ROOT).startsWith(q)).toList();}}
